 3	public final class UnionFindTest {
 4	    private UnionFindTest() {
 5	    }
 6	
 7	    public static void main(String[] args) {
 8	        verifiesEmptyStructure();
 9	        verifiesUnionAndConnectivity();
10	        verifiesComponentSizesAndCounts();
11	        verifiesIndexValidation();
12	    }
13	
14	    private static void verifiesEmptyStructure() {
15	        DisjointSet disjointSet = DisjointSet.create(0);
16	
17	        assertTrue(disjointSet.isEmpty(), "expected empty set to report isEmpty()");
18	        assertEquals(0, disjointSet.size(), "unexpected size for empty set");
19	        assertEquals(0, disjointSet.components(), "unexpected component count for empty set");
20	    }
21	
22	    private static void verifiesUnionAndConnectivity() {
23	        DisjointSet disjointSet = DisjointSet.create(6);
24	
25	        assertTrue(disjointSet.union(0, 1), "first union should merge two components");
26	        assertTrue(disjointSet.union(1, 2), "chained union should merge through compressed roots");
27	        assertFalse(disjointSet.union(0, 2), "union on same component should report no change");
28	        assertTrue(disjointSet.connected(0, 2), "elements 0 and 2 should be connected");
29	        assertFalse(disjointSet.connected(0, 3), "elements 0 and 3 should not be connected");
30	    }
31	
32	    private static void verifiesComponentSizesAndCounts() {
33	        DisjointSet disjointSet = DisjointSet.create(5);
34	
35	        disjointSet.union(0, 1);
36	        disjointSet.union(3, 4);
37	
38	        assertEquals(3, disjointSet.components(), "unexpected component count after merges");
39	        assertEquals(2, disjointSet.componentSize(0), "unexpected component size for root component");
40	        assertEquals(2, disjointSet.componentSize(1), "component size should be consistent within a set");
41	        assertEquals(2, disjointSet.componentSize(3), "unexpected component size for second merged set");
42	        assertEquals(1, disjointSet.componentSize(2), "singleton component should remain size 1");
43	    }
44	
45	    private static void verifiesIndexValidation() {
46	        DisjointSet disjointSet = DisjointSet.create(3);
47	
48	        assertThrows(() -> disjointSet.find(-1), IndexOutOfBoundsException.class);
49	        assertThrows(() -> disjointSet.find(3), IndexOutOfBoundsException.class);
50	        assertThrows(() -> disjointSet.componentSize(4), IndexOutOfBoundsException.class);
51	    }
52	
53	    private static void assertTrue(boolean condition, String message) {
54	        if (!condition) {
55	            throw new AssertionError(message);
56	        }
57	    }
58	
59	    private static void assertFalse(boolean condition, String message) {
60	        assertTrue(!condition, message);
61	    }
62	
63	    private static void assertEquals(int expected, int actual, String message) {
64	        if (expected != actual) {
65	            throw new AssertionError(message + ": expected " + expected + " but was " + actual);
66	        }
67	    }
68	
69	    private static void assertThrows(ThrowingRunnable runnable, Class<? extends Throwable> expectedType) {
70	        try {
71	            runnable.run();
72	        } catch (Throwable throwable) {
73	            if (expectedType.isInstance(throwable)) {
74	                return;
75	            }
76	            throw new AssertionError(
77	                "expected exception " + expectedType.getSimpleName()
78	                    + " but caught "
79	                    + throwable.getClass().getSimpleName(),
80	                throwable
81	            );
82	        }
83	
84	        throw new AssertionError("expected exception " + expectedType.getSimpleName());
85	    }
86	
87	    @FunctionalInterface
88	    private interface ThrowingRunnable {
89	        void run();
90	    }
91	}

